function specialProgram(which){if(which==='symphony'){programSymphony();return true;}if(!['concert','cosmos','aurora','cyber'].includes(which))return false;const sr=seeded(765),r=(a,b)=>a+sr()*(b-a);if(which==='cosmos'){for(let t=.15;t<93;t+=t>80?1.15:t>56?1.8:2.8){let x=.12+sr()*.5,y=.18+sr()*.5;makeCue(t,x,y,t>80?'chrys':t%3<1?'ring':'peony',r(.7,1.4),[3,4,5,2][Math.floor(sr()*4)]);if(t>24)makeCue(t+.4,.15+sr()*.7,.16+sr()*.55,'ring',.8,3)}makeCue(91,.45,.42,'chrys',2.4,6);return true}if(which==='aurora'){for(let t=.1;t<92;t+=t>80?1.6:3.6){const n=t>56?5:3;for(let i=0;i<n;i++)makeCue(t+i*.18,.14+i*.72/(n-1),.36+sr()*.08,t>80?'willow':t%4<2?'strobe':'chrys',t>80?1.2:.85,[5,3,6][i%3])}return true}if(which==='cyber'){for(let t=.1;t<93;t+=t>80?1.3:2.6){const n=t>56?7:5;for(let i=0;i<n;i++){const x=.1+i*.8/(n-1),y=.2+Math.sin(i*1.4+t*.35)*.09;makeCue(t+i*.14,x,y,t>80?'strobe':i%2?'ring':'peony',t>80?1.12:.85,[3,4,8,2][i%4]);if(t>24)makeCue(t+.7+i*.09,1-x,.55,'mine',.5,8,{flight:.5})}if(t>56)makeCue(t+.8,.5,.18,'palm',1.5,4)}return true}const beat=60/128;for(let k=0;k*beat<93;k++){const t=k*beat,intense=t>56;const n=t>80?7:intense?5:3;const every=t>80?2:intense?4:8;if(k%every===0){for(let i=0;i<n;i++)makeCue(t+i*.035,.13+i*.74/(n-1),.22+(i%2)*.09,t>80?'crown':k%16===0?'chrys':'peony',t>80?1.15:.9,[4,2,3,6][(i+Math.floor(k/8))%4])}if(k%(intense?2:4)===0){for(let i=0;i<5;i++)makeCue(t+i*.02,.2+i*.15,.63-i%2*.06,'mine',.4,k%8===0?6:which==='cyber'?3:2,{flight:.42})}}return true}
