$('#tour').onclick=()=>{tour=!tour;$('#tour').setAttribute('aria-pressed',String(tour));$('#tour b').textContent=tour?'自动巡演':'单场循环';$('.footnote>span').textContent=tour?'三个主题自动巡游 · 移开鼠标，沉浸观看':'当前主题自动循环 · 移开鼠标，沉浸观看';toast(tour?'每场结束后自动进入下一个主题':'当前主题将循环播放')};

// The score is the choreography: cues are launched before their intended musical impact.
function programSymphony(){SYMPHONY=SCORES[pov];for(const e of SYMPHONY.events){const flight=e.flower==='comet'?.55:1.5;cues.push({t:e.t-flight,impact:e.t,x:e.x,y:e.y,kind:e.flower,size:e.size,col:e.col,depth:e.depth,flight})}}
function drawSymphony(){gpuEnvironmentActive=renderEnvironmentGL({width:W,height:H,pov,time:showTime,horizon,photos,lights:shellLights,colors:RGB});if(!gpuEnvironmentActive)animateEnvironment();applyCamera();}
initViews();

$('#music-start').onclick=enableSound;
